	@Test
	void directPrecompileSnapshotsOneShotRowsBeforeNameAnalysisAndReplays() {
		AtomicInteger traversals = new AtomicInteger();
		List<BindingSet> expected = List.of(row("shared", "first"), row("shared", "second"));
		Iterable<BindingSet> source = () -> {
			if (traversals.incrementAndGet() != 1) {
				throw new IllegalStateException("VALUES iterable may be traversed only once");
			}
			return expected.iterator();
		};
		BindingSetAssignment assignment = assignment(source);
		QueryRoot root = new QueryRoot(assignment);
		QueryEvaluationStep prepared = strategy().precompile(root);
		BindingSetAssignment preparedAssignment = (BindingSetAssignment) root.getArg();
		assertEquals(Set.of("shared", "first", "second"), preparedAssignment.getBindingNames());
		assertEquals(Set.of("shared"), preparedAssignment.getAssuredBindingNames());
		assertEquals(expected, evaluate(prepared));
		assertEquals(expected, evaluate(prepared));
		assertEquals(1, traversals.get());
		assertSame(source, assignment.getBindingSets());
	}

