	@Test
	void preparationCopiesReusedRowsBeforeAdvancingAndPreservesChangingNames() {
		MapBindingSet reusable = new MapBindingSet(1);
		BindingSetAssignment assignment = assignment(() -> new Iterator<>() {
			private int index;

			@Override
			public boolean hasNext() {
				return index < 2;
			}

			@Override
			public BindingSet next() {
				if (!hasNext()) {
					throw new NoSuchElementException();
				}
				reusable.clear();
				reusable.addBinding(index++ == 0 ? "first" : "second",
						SimpleValueFactory.getInstance().createLiteral(index));
				return reusable;
			}
		});
		QueryRoot root = new QueryRoot(assignment);
		QueryEvaluationStep prepared = strategy().precompile(root);
		reusable.clear();
		List<BindingSet> expected = List.of(numberRow("first", 1), numberRow("second", 2));
		assertEquals(expected, evaluate(prepared));
		assertEquals(expected, evaluate(prepared));
		BindingSetAssignment captured = (BindingSetAssignment) root.getArg();
		assertEquals(Set.of("first", "second"), captured.getBindingNames());
		assertEquals(Set.of(), captured.getAssuredBindingNames());
	}

	@Test
	void preparedCloneAndHashStayStableWhileCallerRowsRemainLive() {
		MapBindingSet sourceRow = row("before");
		List<BindingSet> source = List.of(sourceRow);
		BindingSetAssignment original = assignment(source);
		BindingSetAssignment callerClone = original.clone();
		QueryRoot root = new QueryRoot(original);
		QueryEvaluationStep prepared = strategy().precompile(root);
		BindingSetAssignment captured = (BindingSetAssignment) root.getArg();
		BindingSetAssignment capturedClone = captured.clone();
		int hash = captured.hashCode();
		sourceRow.clear();
		sourceRow.addBinding("after", SimpleValueFactory.getInstance().createLiteral("after"));
		assertEquals(List.of(row("before")), evaluate(prepared));
		assertEquals(captured, capturedClone);
		assertEquals(hash, capturedClone.hashCode());
		assertSame(source, original.getBindingSets());
		assertSame(source, callerClone.getBindingSets());
		assertEquals(Set.of("after"), callerClone.getBindingSets().iterator().next().getBindingNames());
	}

	@Test
	void preparedRowsPreserveUnboundPossibleNamesAndImmutableNameViews() {
		BindingSet sourceRow = new ListBindingSet(List.of("bound", "unbound"),
				Arrays.asList(SimpleValueFactory.getInstance().createLiteral("value"), null));
		QueryRoot root = new QueryRoot(assignment(List.of(sourceRow)));
		strategy().precompile(root);
		BindingSetAssignment captured = (BindingSetAssignment) root.getArg();
		BindingSet row = captured.getBindingSets().iterator().next();
		assertEquals(Set.of("bound", "unbound"), row.getBindingNames());
		assertEquals("value", row.getValue("bound").stringValue());
		assertEquals(null, row.getValue("unbound"));
		assertThrows(UnsupportedOperationException.class, () -> row.getBindingNames().clear());
		assertEquals(Set.of("bound", "unbound"), captured.getBindingNames());
		assertEquals(Set.of("bound"), captured.getAssuredBindingNames());
	}

