	@ParameterizedTest
	@ValueSource(booleans = { false, true })
	void optimizerRefreshCapturesIntroducedSharedRowsBeforeNameAnalysis(boolean experimental) {
		AtomicInteger traversals = new AtomicInteger();
		Iterable<BindingSet> source = oneShotRows(traversals, row("introduced"));
		BindingSetAssignment first = assignment(source);
		BindingSetAssignment second = assignment(source);
		QueryRoot root = new QueryRoot(new SingletonSet());
		DefaultEvaluationStrategy strategy = strategy();
		strategy.setQueryExecutionPolicy(QueryExecutionPolicy.of(experimental));
		List<QueryOptimizer> optimizers = List.of(
				(expression, dataset, bindings) -> {
					root.setArg(new Union(root.getArg(), first));
					QueryEvaluationUtility.refreshQuerySafetySnapshot(root);
					assertEquals(Set.of("introduced"), expression.getBindingNames());
				},
				(expression, dataset, bindings) -> {
					root.setArg(new Union(root.getArg(), second));
					QueryEvaluationUtility.refreshQuerySafetySnapshot(root);
					assertEquals(Set.of("introduced"), expression.getBindingNames());
				});
		strategy.setOptimizerPipeline(() -> optimizers);
		TupleExpr optimized = strategy.optimize(root, new EvaluationStatistics(), EmptyBindingSet.getInstance());
		QueryEvaluationStep prepared = strategy.precompile(optimized);
		List<BindingSet> expected = List.of(EmptyBindingSet.getInstance(), row("introduced"), row("introduced"));
		assertEquals(expected, evaluate(prepared));
		assertEquals(expected, evaluate(prepared));
		assertEquals(1, traversals.get());
		assertSame(source, first.getBindingSets());
		assertSame(source, second.getBindingSets());
	}

