	@Test
	void retainedSafetySnapshotKeepsBareRootFactsAfterPreparationCloses() {
		AtomicInteger traversals = new AtomicInteger();
		Iterable<BindingSet> source = oneShotRows(traversals, row("x"));
		BindingSetAssignment introduced = assignment(source);
		var snapshot = QueryEvaluationUtility.withPreparedQuerySafetySnapshot(new SingletonSet(),
				PreparedValuesSnapshot::newPreparation,
				ignored -> QueryEvaluationUtility.querySafetySnapshot(introduced));
		assertTrue(snapshot.isRepeatable(introduced));
		assertTrue(snapshot.permitsBindingInjection(introduced, Set.of("x")));
		assertTrue(snapshot.isRepeatable(introduced));
		QueryEvaluationUtility.withPreparedQuerySafetySnapshot(new SingletonSet(),
				PreparedValuesSnapshot::newPreparation, ignored -> {
					assertTrue(snapshot.isRepeatable(introduced));
					return null;
				});
		assertEquals(1, traversals.get());
		assertSame(source, introduced.getBindingSets());
	}

	private static Iterable<BindingSet> oneShotRows(AtomicInteger traversals, BindingSet row) {
		return () -> {
			if (traversals.incrementAndGet() != 1) {
				throw new IllegalStateException("introduced VALUES iterable may be traversed only once");
			}
			return List.of(row).iterator();
		};
	}

	private static DefaultEvaluationStrategy strategy() {
		return new DefaultEvaluationStrategy(new EmptyTripleSource(), null);
	}

	private static BindingSetAssignment assignment(Iterable<BindingSet> rows) {
		BindingSetAssignment assignment = new BindingSetAssignment();
		assignment.setBindingSets(rows);
		return assignment;
	}

	private static List<BindingSet> evaluate(QueryEvaluationStep prepared) {
		List<BindingSet> rows = new ArrayList<>();
		try (var iteration = prepared.evaluate(EmptyBindingSet.getInstance())) {
			while (iteration.hasNext()) {
				rows.add(iteration.next());
			}
		}
		return rows;
	}

	private static MapBindingSet row(String... names) {
		MapBindingSet row = new MapBindingSet(names.length);
		for (String name : names) {
			row.addBinding(name, SimpleValueFactory.getInstance().createLiteral(name));
		}
		return row;
	}

	private static MapBindingSet numberRow(String name, int value) {
		MapBindingSet row = new MapBindingSet(1);
		row.addBinding(name, SimpleValueFactory.getInstance().createLiteral(value));
		return row;
	}
